import{_ as a,o as t,c as i,ax as s}from"./chunks/framework.D0-oyZN4.js";const u=JSON.parse(`{"title":"Share Dependencies Across Widgets","description":"Let widgets on the same page share one copy of a common dependency instead of each bundling its own, using the Developer Studio CLI's automatic deduplication.","frontmatter":{"description":"Let widgets on the same page share one copy of a common dependency instead of each bundling its own, using the Developer Studio CLI's automatic deduplication."},"headers":[],"relativePath":"cli/share-dependencies.md","filePath":"cli/share-dependencies.md"}`),d={name:"cli/share-dependencies.md"};function n(o,e,r,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/share-dependencies.md for this page in Markdown format</div><h1 id="share-dependencies-across-widgets" tabindex="-1">Share Dependencies Across Widgets <a class="header-anchor" href="#share-dependencies-across-widgets" aria-label="Permalink to &quot;Share Dependencies Across Widgets&quot;">​</a></h1><p>Use this guide when two or more widgets in your project depend on the same package — for example a shared UI library — and you want the community to load one copy instead of one per widget.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Two or more widgets under <code>widgets/</code> that declare the same package in <code>package.json</code> <code>dependencies</code></li></ul><h2 id="share-a-dependency-between-widgets" tabindex="-1">Share a dependency between widgets <a class="header-anchor" href="#share-a-dependency-between-widgets" aria-label="Permalink to &quot;Share a dependency between widgets&quot;">​</a></h2><p>Add the package as a normal dependency to each widget that needs it, then rebuild:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gsds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Any package declared in two or more widgets&#39; <code>dependencies</code> is <strong>shared</strong>. <code>gsds build</code> externalizes it out of those widgets&#39; bundles automatically — no flag, no extra step. <code>extensions_registry.json</code> gets an <code>importMaps</code> entry pointing the shared package at its resolved version, so widgets on the same community page load one copy instead of one apiece.</p><p>A package only one widget uses stays bundled in that widget; nothing changes until a second widget declares the same dependency.</p><p><code>devDependencies</code> never participate — build-time-only packages never reach the browser.</p><h2 id="exclude-a-package-from-deduplication" tabindex="-1">Exclude a package from deduplication <a class="header-anchor" href="#exclude-a-package-from-deduplication" aria-label="Permalink to &quot;Exclude a package from deduplication&quot;">​</a></h2><p>Some packages break when served as a single shared copy — most commonly a CSS-in-JS library whose independently built copies don&#39;t share a class-name registry, causing style collisions with no build-time error. Exclude a package or an entire scope in <code>gsds.json</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dedupe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;exclude&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@angular/*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;styled-components&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>A trailing <code>/*</code> excludes an entire scope. There is no single flag to turn deduplication off project-wide — <code>dedupe.exclude</code> is the only opt-out, by design: deduplication only ever activates for a package two or more widgets actually declare, so excluding the specific packages you don&#39;t want shared has the same effect.</p><p><code>gsds init</code> seeds new projects with <code>@angular/*</code> excluded, and backfills it into any existing <code>gsds.json</code> that predates this feature and has no <code>dedupe</code> key at all. Angular packages served raw from a module CDN skip the Angular Linker and break at runtime — Angular widgets need their <code>@angular/*</code> packages bundled, not shared. Non-Angular dependencies that two Angular widgets happen to share (<code>rxjs</code>, <code>tslib</code>, or any third-party library) still deduplicate normally.</p><h2 id="if-two-widgets-need-different-versions" tabindex="-1">If two widgets need different versions <a class="header-anchor" href="#if-two-widgets-need-different-versions" aria-label="Permalink to &quot;If two widgets need different versions&quot;">​</a></h2><p>If two widgets share a dependency but resolve it to different installed versions, <code>gsds build</code> fails and names every widget/version pair — there is one import map entry per registry, so one version has to win.</p><p><strong>Recover:</strong> Align the versions across the affected widgets, or remove the dependency from one of them, then re-run <code>gsds build</code>.</p><h2 id="if-a-widget-s-build-file-can-t-be-patched-automatically" tabindex="-1">If a widget&#39;s build file can&#39;t be patched automatically <a class="header-anchor" href="#if-a-widget-s-build-file-can-t-be-patched-automatically" aria-label="Permalink to &quot;If a widget&#39;s build file can&#39;t be patched automatically&quot;">​</a></h2><p><code>gsds build</code> makes externalization take effect by patching the widget&#39;s build config in place: the <code>externalPackages</code> array in <code>vite.config.ts</code>, or <code>architect.build.options.externalDependencies</code> in <code>angular.json</code> for Angular widgets. Nothing else in either file is touched.</p><p>A widget scaffolded before this feature existed has no <code>externalPackages</code> declaration yet — <code>gsds build</code> migrates it into the current shape automatically the first time that widget actually shares a dependency with another. This only fails, with a warning naming the widget, when the file&#39;s shape can&#39;t be confidently patched — a custom <code>rollupOptions</code>, or a build block laid out differently than the standard template.</p><p><strong>Recover:</strong> Copy the externals block from a freshly scaffolded widget&#39;s <code>vite.config.ts</code> into the named widget&#39;s file.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Flags and exit behavior for <code>gsds build</code> in the <a href="./reference/commands.html#gsds-build">Command Reference</a></li><li>Which files <code>gsds build</code> patches in <a href="./reference/project-files.html">Project Files</a></li><li>Error text for version conflicts and patch failures in <a href="./reference/troubleshooting.html">Troubleshooting</a></li></ul>',25)])])}const g=a(d,[["render",n]]);export{u as __pageData,g as default};
